public static void attachStation(SceneBuilder builder, SceneBuildingUtil util) {
    CreateSceneBuilder scene = new CreateSceneBuilder(builder);
    scene.title("brass_chunk_loader_station", "Loading Chunks For Train Stations");
    scene.configureBasePlate(30, 0, 9);
    scene.scaleSceneView(0.75f);
    scene.world().cycleBlockProperty(util.grid().at(60, 3, 6), (Property)BlazeBurnerBlock.HEAT_LEVEL);
    BlockPos chunkLoader = util.grid().at(34, 1, 2);
    Selection selectLoader = util.select().position(chunkLoader);
    BlockPos trainStation = util.grid().at(34, 1, 3);
    Selection train = util.select().fromTo(57, 2, 7, 61, 3, 5);
    Selection load = util.select().layer(0).add(selectLoader).add(util.select().position(trainStation));
    scene.showBasePlate();
    scene.idle(5);
    scene.world().showSection(util.select().layersFrom(1).substract(selectLoader), Direction.DOWN);
    scene.idle(10);
    scene.world().showSection(selectLoader, Direction.SOUTH);
    scene.idle(20);
    scene.overlay().showText(50).text("Brass chunk loaders can attach to Train Stations").pointAt(util.vector().blockSurface(chunkLoader, Direction.WEST)).attachKeyFrame().placeNearTarget();
    scene.idle(70);
    scene.overlay().showText(50).text("Place them next to Train Stations in the correct direction").pointAt(util.vector().blockSurface(chunkLoader, Direction.WEST)).placeNearTarget();
    scene.idle(70);
    scene.overlay().chaseBoundingBoxOutline(PonderPalette.BLUE, (Object)chunkLoader, new AABB(chunkLoader), 150);
    scene.world().hideSection(load, null);
    scene.idle(10);
    scene.overlay().showText(60).text("They do not require rotational power, but are normally inactive").pointAt(util.vector().blockSurface(chunkLoader, Direction.WEST)).attachKeyFrame().placeNearTarget();
    scene.idle(80);

